export type ChatRole = "system" | "user" | "assistant" | "tool";

export type ChatMessage = {
  /** Stable id used as React key and as `data-message-id` for the scroller. */
  id: string;
  role: ChatRole;
  content: string;
  /** Original id coming back from an assistant `tool_call`, kept for the follow-up request. */
  toolCallId?: string;
  /** Name of the tool that produced a `tool` message. */
  name?: string;
  /** Tool calls the model asked for, echoed back on later turns. */
  toolCalls?: ToolCall[];
  timestamp?: string;
};

/** Shape callers and the API speak; ids are generated by `newChatMessage`. */
export type NewChatMessage = Omit<ChatMessage, "id">;

export type ToolParameters = {
  type: "object";
  properties: Record<string, unknown>;
  required?: string[];
};

export type ToolDefinition = {
  type: "function";
  function: {
    name: string;
    description?: string;
    parameters: ToolParameters;
  };
};

export type ToolHandler = (args: Record<string, unknown>) => Promise<unknown> | unknown;

export type ToolCall = {
  id: string;
  function: {
    name: string;
    arguments?: string;
  };
};

export type ApiMessage = {
  role: ChatRole;
  content: string | null;
  tool_call_id?: string;
  tool_calls?: ToolCall[];
};

export type ChatCompletionResponse = {
  choices?: Array<{
    message?: {
      content?: string | null;
      tool_calls?: ToolCall[];
    };
  }>;
};

/** Everything the transport needs for one request, except the endpoint itself. */
export type ChatRequest = {
  messages: ApiMessage[];
  tools?: ToolDefinition[];
  toolChoice?: "auto" | "none" | "required";
};
